def interpolation_search(a, target):
    low, high = 0, len(a) - 1
    while low <= high and a[low] <= target <= a[high]:
        if a[low] == a[high]:
            return low if a[low] == target else -1
        # estimate position from value distribution
        pos = low + (target - a[low]) * (high - low) // (a[high] - a[low])
        if a[pos] == target:
            return pos
        elif a[pos] < target:
            low = pos + 1
        else:
            high = pos - 1
    return -1

